"use client";

import { useState, useEffect } from "react";

type Bookmark = {
    id: number;
    title: string;
    url: string;
};

export default function List() {

    const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

    useEffect(() => {
        async function fetchBookmarks() {
            try {
                const response = await fetch("/api/bookmarks", { method: "GET" });
                const data = await response.json();
                setBookmarks(data);
            } catch (error) {
                console.error("Error fetching bookmarks:", error);
            }
        }
        fetchBookmarks();
    }, []);

    return (
        <>
            <div>
                {bookmarks.map((bookmark) => (
                    <div key={bookmark.id} className="flex items-center w-[80rem] h-[4rem] bg-gray-400 rounded p-4 gap-20">
                        <input
                            readOnly
                            type="text"
                            placeholder="Name"
                            value={bookmark.title ?? ""}
                            className="outline-none border-grey-400 px-2 text-2xl"
                        />

                        <input
                            readOnly
                            type="text"
                            value={bookmark.url ?? ""}
                            className="outline-none border-grey-400 px-2 flex-1 text-2xl"
                        />

                        <button className="ml-2 px-3 py-1 bg-red-500 text-white rounded">
                            Delete
                        </button>
                    </div>))}
            </div>
        </>
    )
}